from fastapi import APIRouter, HTTPException
from backend.models.task import Task, TaskCreate, TaskUpdate, TaskStatus
from typing import List

router = APIRouter(
    prefix="/tasks",
    tags=["tasks"]
)

# In-memory storage for demonstration purposes
# In a real application, this would be a database session
tasks_db: dict[str, Task] = {}

@router.get("/", response_model=List[Task])
def get_tasks():
    """Return all tasks."""
    return list(tasks_db.values())

@router.post("/", response_model=Task)
def create_task(task_data: TaskCreate):
    """Create a new task."""
    new_task = Task(**task_data.model_dump())
    tasks_db[new_task.id] = new_task
    return new_task

@router.patch("/{task_id}", response_model=Task)
def update_task(task_id: str, task_update: TaskUpdate):
    """Update an existing task's status or details."""
    if task_id not in tasks_db:
        raise HTTPException(status_code=404, detail="Task not found")

    current_task = tasks_db[task_id]
    update_data = task_update.model_dump(exclude_unset=True)

    # Update fields
    for key, value in update_data.items():
        setattr(current_task, key, value)

    tasks_db[task_id] = current_task
    return current_task

@router.delete("/{task_id}")
def delete_task(task_id: str):
    """Delete a task by ID."""
    if task_id not in tasks_db:
        raise HTTPException(status_code=404, detail="Task not found")

    del tasks_db[task_id]
    return {"message": "Task deleted successfully"}

