  const [backendReady, setBackendReady] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const init = async () => {
      const isReady = await checkBackendHealth();
      setBackendReady(isReady);
      if (isReady) {
        await fetchTasks();
      } else {
        alert('Backend server is not running. Please start the FastAPI server.');
      }
      setLoading(false);
    };
    init();
  }, []);

  const fetchTasks = async () => {
    try {
      const data = await getAllTasks();
      setTasks(data);
    } catch (error) {
      console.error('Failed to fetch tasks', error);
    }
  };

  const handleAddTask = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTitle.trim()) return;

    try {
      const task = await createTask({
        title: newTitle,
        assignee: newAssignee || undefined
      });
      setTasks([...tasks, task]);
      setNewTitle('');
      setNewAssignee('');
    } catch (error) {
      console.error('Failed to add task', error);
    }
  };

  const cycleStatus = (currentStatus: Task['status']): Task['status'] => {
    switch (currentStatus) {
      case 'pending': return 'in_progress';
      case 'in_progress': return 'done';
      case 'done': return 'pending';
      default: return 'pending';
    }
  };

  const handleStatusClick = async (task: Task) => {
    const nextStatus = cycleStatus(task.status);
    try {
      const updatedTask = await updateTaskStatus(task.id, nextStatus);
      setTasks(tasks.map(t => t.id === task.id ? updatedTask : t));
    } catch (error) {
      console.error('Failed to update status', error);
    }
  };

  const handleDelete = async (taskId: string) => {
    if (window.confirm('Are you sure you want to delete this task?')) {
      try {
        await deleteTask(taskId);
        setTasks(tasks.filter(t => t.id !== taskId));
      } catch (error) {
        console.error('Failed to delete task', error);
      }
    }
  };

  if (loading) return <div>Loading...</div>;
  if (!backendReady) return <div>Please start the backend server.</div>;

  return (
    <div style={{ padding: '20px', maxWidth: '800px', margin: '0 auto' }}>
      <h1>Task System</h1>

      <form onSubmit={handleAddTask} style={{ marginBottom: '20px', display: 'flex', gap: '10px' }}>
        <input 
          type="text" 
          placeholder="Task Title" 
          value={newTitle} 
          onChange={(e) => setNewTitle(e.target.value)} 
          required
          style={{ flex: 2 }}
        />
        <input 
          type="text" 
          placeholder="Assignee (Optional)" 
          value={newAssignee} 
          onChange={(e) => setNewAssignee(e.target.value)} 
          style={{ flex: 1 }}
        />
        <button type="submit">Add Task</button>
      </form>

      <ul style={{ listStyleType: 'none', padding: 0 }}>
        {tasks.map((task) => (
          <li key={task.id} style={{ border: '1px solid #ccc', padding: '10px', marginBottom: '10px', borderRadius: '4px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div>
              <strong>{task.title}</strong>
              <br />
              <small>Status: 
                <span 
                  onClick={() => handleStatusClick(task)} 
                  style={{ cursor: 'pointer', color: task.status === 'done' ? 'green' : task.status === 'in_progress' ? 'orange' : 'gray', marginLeft: '5px' }}
                  title="Click to change status"
                >
                  [{task.status}]
                </span>
              </small>
              <br />
              <small>Assignee: {task.assignee || 'Unassigned'}</small>
              <br />
              <small>Created: {new Date(task.created_at).toLocaleString()}</small>
            </div>
            <button 
              onClick={() => handleDelete(task.id)} 
              style={{ background: 'red', color: 'white', border: 'none', padding: '5px 10px', cursor: 'pointer', borderRadius: '4px' }}
            >
              Delete
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default TaskList;

